//! SCAN.MESHOP.CUT.INVERT acceptance tests (kernel half; the command half, AC-3's "journals
//! nothing", is in `fid-scan-mesh-cmd`). Expected triangles, flags, digests, orientation
//! signs, misoriented pairs and negated-normal sets are in
//! `fixtures/scan/meshop/invert_cases.txt`, written by the independent Python reference
//! `fixtures/scan/meshop/make_invert_cases.py` from the spec's rules; nothing here was
//! generated by running this crate.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_geo_sel::{Domain, EntityId, Selection, SelectionBody, SelectionQuery};
use fid_geo_types::{
    digest_mesh, AttributeSet, FrameRef, GeometryElement, Mesh, MeshOptions, PointBuffer, TriangleAttrs,
};
use fid_scan_mesh::cut::invert::{plan, INVERT_NORMALS, SELECTION_DOMAIN, SELECTION_NOT_INDEX_SET, STALE_SELECTION};
use fid_scan_mesh::{
    check_input_intact, invert_normals, InvertParams, MeshOp, MeshOpBuilder, MeshOpError, MeshOpOutput, MeshView,
    Registered, TriRef, VerifiedMeshView,
};
use fid_types::{Determinism, Digest};

// ---------------------------------------------------------------- fixtures

fn read(rel: &str) -> String {
    std::fs::read_to_string(format!("{}/fixtures/scan/{rel}", fid_testkit::WORKSPACE_ROOT)).unwrap()
}

fn load(name: &str) -> (FrameRef, Vec<[f64; 3]>, Vec<[u64; 3]>) {
    let text = read(&format!("{name}.txt"));
    let mut frame = None;
    let (mut v, mut t) = (Vec::new(), Vec::new());
    for line in text.lines().filter(|l| !l.starts_with('#') && !l.is_empty()) {
        let parts: Vec<&str> = line.split(' ').collect();
        match parts[0] {
            "frame" => {
                let mut b = [0u8; 16];
                for (i, byte) in b.iter_mut().enumerate() {
                    *byte = u8::from_str_radix(&parts[1][2 * i..2 * i + 2], 16).unwrap();
                }
                frame = Some(FrameRef::from_bytes(b));
            }
            "v" => v.push([parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap()]),
            "t" => t.push([parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap()]),
            other => panic!("unknown line kind {other}"),
        }
    }
    (frame.unwrap(), v, t)
}

fn cube() -> Mesh {
    let (f, v, t) = load("mesh_closed_cube");
    Mesh::from_points(f, &v, &t).unwrap()
}

/// One `case` block of the reference file, as key -> value.
fn case(name: &str) -> Vec<(String, String)> {
    let text = read("meshop/invert_cases.txt");
    let mut out = Vec::new();
    let mut inside = false;
    for line in text.lines().filter(|l| !l.starts_with('#')) {
        let (k, v) = line.split_once(' ').unwrap_or((line, ""));
        if k == "case" {
            inside = v == name;
            continue;
        }
        if inside {
            if k == "end" {
                return out;
            }
            out.push((k.to_string(), v.to_string()));
        }
    }
    panic!("no case {name}");
}

fn get<'a>(c: &'a [(String, String)], key: &str) -> &'a str {
    c.iter().find(|(k, _)| k == key).map(|(_, v)| v.as_str()).unwrap_or_else(|| panic!("no key {key}"))
}

fn digest(c: &[(String, String)], key: &str) -> Digest {
    Digest::parse(get(c, key)).unwrap()
}

fn triangles(c: &[(String, String)]) -> Vec<[u64; 3]> {
    get(c, "triangles")
        .split(' ')
        .map(|t| {
            let p: Vec<u64> = t.split(',').map(|x| x.parse().unwrap()).collect();
            [p[0], p[1], p[2]]
        })
        .collect()
}

fn numbers(c: &[(String, String)], key: &str) -> Vec<u64> {
    get(c, key).split(' ').filter(|s| !s.is_empty()).map(|s| s.parse().unwrap()).collect()
}

fn raw_view(m: &Mesh) -> VerifiedMeshView<'_> {
    MeshView::unflagged(m).verified(&digest_mesh(m).to_digest()).unwrap()
}

fn out_view(o: &MeshOpOutput) -> VerifiedMeshView<'_> {
    MeshView::of_output(o).unwrap().verified(&o.output_digest()).unwrap()
}

fn tris_of(m: &Mesh) -> Vec<[u64; 3]> {
    m.triangles().collect()
}

fn flags_of(o: &MeshOpOutput) -> String {
    (0..o.mesh().triangle_count()).map(|t| if o.synthesized().get(t).unwrap() { '1' } else { '0' }).collect()
}

/// '-' where a triangle's normal points to the cube centre, '+' where it points away (the
/// reference computes the same signs; the cube's coordinates are 0 and 1, so this is exact).
fn orientation(m: &Mesh) -> String {
    m.triangles()
        .map(|[a, b, c]| {
            let (pa, pb, pc) = (m.vertex(a).unwrap(), m.vertex(b).unwrap(), m.vertex(c).unwrap());
            let u = [pb[0] - pa[0], pb[1] - pa[1], pb[2] - pa[2]];
            let v = [pc[0] - pa[0], pc[1] - pa[1], pc[2] - pa[2]];
            let n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
            let d: f64 = (0..3).map(|k| n[k] * ((pa[k] + pb[k] + pc[k]) / 3.0 - 0.5)).sum();
            assert!(d != 0.0);
            if d < 0.0 {
                '-'
            } else {
                '+'
            }
        })
        .collect()
}

/// Checks an output against its reference case.
fn check_case(out: &MeshOpOutput, name: &str) {
    let c = case(name);
    assert_eq!(out.inputs(), &[digest(&c, "input_digest")], "{name}");
    assert_eq!(tris_of(out.mesh()), triangles(&c), "{name}");
    assert_eq!(flags_of(out), get(&c, "flags"), "{name}");
    assert_eq!(digest_mesh(out.mesh()).to_digest(), digest(&c, "element_digest"), "{name}");
    assert_eq!(out.output_digest(), digest(&c, "output_digest"), "{name}");
    let facts = out.mesh().facts();
    assert_eq!(facts.boundary_edges.to_string(), get(&c, "boundary_edges"), "{name}");
    assert_eq!(facts.misoriented_pairs.to_string(), get(&c, "misoriented_pairs"), "{name}");
    assert_eq!(orientation(out.mesh()), get(&c, "orientation"), "{name}");
    assert_eq!(out.op().as_str(), INVERT_NORMALS);
    assert_eq!(out.determinism(), Determinism::D0);
    assert_eq!(out.seed(), None);
}

fn select(m: &Mesh, domain: Domain, indices: &[u64]) -> Selection {
    Selection::on_element(EntityId::from_bytes([7; 16]), &GeometryElement::Mesh(m.clone()), domain, indices).unwrap()
}

/// A test operation that marks triangle 0 synthesized (create) and copies the rest, so a
/// flagged input exists (callers cannot attach flags directly).
struct Mark;

impl MeshOp for Mark {
    const ID: &'static str = "mesh.test_mark@1";
    const DETERMINISM: Determinism = Determinism::D0;
    type Params = ();

    fn run(&self, inputs: &[VerifiedMeshView<'_>], _: &(), out: &mut MeshOpBuilder<'_, '_>) -> Result<(), MeshOpError> {
        let m = inputs[0].mesh();
        for v in 0..m.vertex_count() {
            out.copy_vertex(0, v)?;
        }
        out.create_triangle(m.triangle(0).unwrap())?;
        for t in 1..m.triangle_count() {
            out.copy_triangle(TriRef::new(0, t))?;
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- AC-1

#[test]
fn ac1_whole_mesh_points_inward_and_twice_reproduces_the_input() {
    let m = cube();
    let input = case("input");
    assert_eq!(digest_mesh(&m).to_digest(), digest(&input, "element_digest"));
    assert_eq!(orientation(&m), get(&input, "orientation"));

    let once = invert_normals(raw_view(&m), &InvertParams::whole()).unwrap();
    check_case(&once, "whole");
    assert!(orientation(once.mesh()).chars().all(|c| c == '-'), "every face normal points inward");
    check_input_intact(&MeshView::unflagged(&m), &digest_mesh(&m).to_digest()).unwrap();
    assert_eq!(once.params_json(), br#"{"target":"all"}"#);

    let twice = invert_normals(out_view(&once), &InvertParams::whole()).unwrap();
    check_case(&twice, "twice");
    // The geometry, and so the GEO.TYPES element digest, comes back exactly. The version
    // digest is the derived-mesh digest of PROV (a raw input has no attribute).
    assert_eq!(twice.mesh(), &m);
    assert_eq!(digest_mesh(twice.mesh()), digest_mesh(&m));

    // A third inversion reproduces the first output's version digest exactly.
    let thrice = invert_normals(out_view(&twice), &InvertParams::whole()).unwrap();
    assert_eq!(thrice.output_digest(), once.output_digest());
}

/// REQ-003 on a flagged input: inverting the same selection twice gives back the input's
/// version digest, flags included.
#[test]
fn twice_reproduces_the_version_digest_of_a_flagged_input() {
    let m = cube();
    let marked = Registered::new(Mark).unwrap().run(&[raw_view(&m)], &()).unwrap();
    let c = case("flag_once");
    assert_eq!(marked.output_digest(), digest(&c, "input_digest"));

    let sel = select(marked.mesh(), Domain::Triangles, &[0, 1]);
    let params = InvertParams::from_selection(&sel, marked.mesh()).unwrap();
    let once = invert_normals(out_view(&marked), &params).unwrap();
    check_case(&once, "flag_once");

    let sel2 = select(once.mesh(), Domain::Triangles, &[0, 1]);
    let params2 = InvertParams::from_selection(&sel2, once.mesh()).unwrap();
    let twice = invert_normals(out_view(&once), &params2).unwrap();
    check_case(&twice, "flag_twice");
    assert_eq!(twice.output_digest(), marked.output_digest());
}

// ---------------------------------------------------------------- AC-2

#[test]
fn ac2_one_face_changes_only_its_triangles_and_misorients_its_border() {
    let m = cube();
    let sel = select(&m, Domain::Triangles, &[0, 1]);
    let params = InvertParams::from_selection(&sel, &m).unwrap();
    let p = plan(&m, &params).unwrap();
    assert_eq!(p.triangle_count(), 2);
    assert_eq!(p.vertex_count(), 0);

    let out = invert_normals(raw_view(&m), &params).unwrap();
    check_case(&out, "face_z0");
    for (t, (before, after)) in tris_of(&m).iter().zip(tris_of(out.mesh())).enumerate() {
        if t < 2 {
            assert_eq!(after, [before[0], before[2], before[1]]);
        } else {
            assert_eq!(&after, before, "triangle {t} must not change");
        }
    }
    let facts = out.mesh().facts();
    assert_eq!(facts.misoriented_pairs, 4, "the four border edges of the face");
    assert!(!facts.oriented);
    assert!(facts.closed);
    let sel_digest = sel.content_digest().unwrap().to_digest();
    assert_eq!(params.selection_digest(), Some(sel_digest));
    assert_eq!(
        out.params_json(),
        format!(r#"{{"selection":"{}","target":"selection","triangles":"2"}}"#, sel_digest.as_str()).as_bytes()
    );
}

// ---------------------------------------------------------------- AC-3

#[test]
fn ac3_stale_and_unusable_selections_are_refused() {
    let m = cube();
    let sel = select(&m, Domain::Triangles, &[0, 1]);
    let changed = invert_normals(raw_view(&m), &InvertParams::whole()).unwrap();
    // The selection was made on the cube, not on the inverted version.
    let e = InvertParams::from_selection(&sel, changed.mesh()).unwrap_err();
    assert_eq!(e.code(), STALE_SELECTION);
    // Parameters bound to the cube cannot run on another mesh either.
    let params = InvertParams::from_selection(&sel, &m).unwrap();
    let e = invert_normals(out_view(&changed), &params).unwrap_err();
    assert_eq!(e.code(), STALE_SELECTION);
    assert_eq!(plan(changed.mesh(), &params).unwrap_err().code(), STALE_SELECTION);

    let points = select(&m, Domain::Points, &[0]);
    assert_eq!(InvertParams::from_selection(&points, &m).unwrap_err().code(), SELECTION_DOMAIN);
    let query = Selection::new(
        EntityId::from_bytes([7; 16]),
        digest_mesh(&m),
        SelectionBody::Query(SelectionQuery::from_bytes(b"{}".to_vec()).unwrap()),
    );
    assert_eq!(InvertParams::from_selection(&query, &m).unwrap_err().code(), SELECTION_NOT_INDEX_SET);
}

// ---------------------------------------------------------------- REQ-002, normals and channels

/// The cube with unit normals (0, 0, -1) at z = 0 and (0, 0, 1) at z = 1, an intensity
/// channel and per-triangle quality flags.
fn cube_with_channels() -> Mesh {
    let (f, v, t) = load("mesh_closed_cube");
    let x = v.iter().map(|p| p[0]).collect();
    let y = v.iter().map(|p| p[1]).collect();
    let z = v.iter().map(|p| p[2]).collect();
    let nz: Vec<f64> = v.iter().map(|p| if p[2] == 0.0 { -1.0 } else { 1.0 }).collect();
    let attrs = AttributeSet {
        normal: Some([vec![0.0; v.len()], vec![0.0; v.len()], nz]),
        intensity: Some((0..v.len()).map(|i| i as f32).collect()),
        ..AttributeSet::default()
    };
    let opts = MeshOptions {
        triangle_attrs: TriangleAttrs { scanner_id: None, quality: Some((0..t.len() as u16).collect()) },
        ..MeshOptions::default()
    };
    Mesh::with_options(f, PointBuffer::new(x, y, z), attrs, t, opts).unwrap()
}

fn negated(before: &Mesh, after: &Mesh) -> Vec<u64> {
    (0..before.vertex_count())
        .filter(|&v| {
            let (a, b) = (before.vertex_attrs().normal_at(v).unwrap(), after.vertex_attrs().normal_at(v).unwrap());
            if a == b {
                false
            } else {
                assert_eq!(b, [-a[0], -a[1], -a[2]], "vertex {v}: a normal is kept or negated");
                true
            }
        })
        .collect()
}

#[test]
fn normals_are_negated_exactly_where_every_incident_triangle_is_targeted() {
    let m = cube_with_channels();
    for name in ["negate_whole", "negate_z0", "negate_corner0"] {
        let c = case(name);
        let targets = numbers(&c, "targets");
        let params = if targets.len() as u64 == m.triangle_count() {
            InvertParams::whole()
        } else {
            InvertParams::from_selection(&select(&m, Domain::Triangles, &targets), &m).unwrap()
        };
        let out = invert_normals(raw_view(&m), &params).unwrap();
        assert_eq!(negated(&m, out.mesh()), numbers(&c, "negated"), "{name}");
        assert_eq!(plan(&m, &params).unwrap().vertex_count(), numbers(&c, "negated").len() as u64, "{name}");
        // Other channels and the per-triangle attributes are kept.
        assert_eq!(out.mesh().vertex_attrs().intensity, m.vertex_attrs().intensity, "{name}");
        assert_eq!(out.mesh().triangle_attrs(), m.triangle_attrs(), "{name}");
        // Self-inverse: the second inversion reproduces the input bit for bit, channels
        // included (fresh selection on the changed version).
        let params2 = if params.is_whole() {
            InvertParams::whole()
        } else {
            InvertParams::from_selection(&select(out.mesh(), Domain::Triangles, &targets), out.mesh()).unwrap()
        };
        let twice = invert_normals(out_view(&out), &params2).unwrap();
        assert_eq!(twice.mesh(), &m, "{name}");
        assert_eq!(digest_mesh(twice.mesh()), digest_mesh(&m), "{name}");
    }
}

#[test]
fn an_unreferenced_vertex_keeps_its_normal() {
    let (f, v, t) = load("mesh_unused_vertex");
    let n = v.len();
    let attrs = AttributeSet { normal: Some([vec![1.0; n], vec![0.0; n], vec![0.0; n]]), ..AttributeSet::default() };
    let pb = PointBuffer::new(
        v.iter().map(|p| p[0]).collect(),
        v.iter().map(|p| p[1]).collect(),
        v.iter().map(|p| p[2]).collect(),
    );
    let m = Mesh::new(f, pb, attrs, t).unwrap();
    let out = invert_normals(raw_view(&m), &InvertParams::whole()).unwrap();
    assert_eq!(out.mesh().vertex_count(), m.vertex_count(), "the unreferenced vertex is kept");
    assert_eq!(negated(&m, out.mesh()), numbers(&case("negate_unused_whole"), "negated"));
}

// ---------------------------------------------------------------- REQ-004, D0

#[test]
fn runs_are_deterministic_and_leave_the_input_intact() {
    let m = cube_with_channels();
    let before = digest_mesh(&m).to_digest();
    let params = InvertParams::from_selection(&select(&m, Domain::Triangles, &[3, 4, 5]), &m).unwrap();
    let a = invert_normals(raw_view(&m), &params).unwrap();
    let b = invert_normals(raw_view(&m), &params).unwrap();
    assert_eq!(a.record_json(), b.record_json());
    assert_eq!(a.record_digest(), b.record_digest());
    assert_eq!(a.output_digest(), b.output_digest());
    check_input_intact(&MeshView::unflagged(&m), &before).unwrap();
    assert_eq!(digest_mesh(&m).to_digest(), before);
}

#[test]
fn an_empty_selection_changes_nothing_but_the_version() {
    let m = cube();
    let params = InvertParams::from_selection(&select(&m, Domain::Triangles, &[]), &m).unwrap();
    let out = invert_normals(raw_view(&m), &params).unwrap();
    assert_eq!(out.mesh(), &m);
    assert_eq!(plan(&m, &params).unwrap().triangle_count(), 0);
}
